<form class="card-s mb-3 row g-2 align-items-end" method="get"><div class="col-md-5"><label class="form-label" for="sid">الشعبة</label><select class="form-select" id="sid" name="section_id" data-autosubmit><option value="">كل الشعب</option><?php foreach ($sections as $s): ?><option value="<?= (int)$s['id'] ?>" <?= (int)$sectionId === (int)$s['id'] ? 'selected' : '' ?>><?= e($s['grade_name'] . ' / ' . $s['name']) ?></option><?php endforeach; ?></select></div>
  <div class="col-md-7 d-flex flex-wrap gap-2 justify-content-md-end"><?php if (can('fees.collect')): ?><button type="button" class="btn btn-warning remind-btn" data-channel="sms" data-url="<?= url('api/v1/school/fees/remind') ?>"><i class="bi bi-chat-dots"></i> تذكير المحدَّدين بـ SMS</button><?php if (!empty($wa)): ?><button type="button" class="btn btn-success remind-btn" data-channel="whatsapp" data-url="<?= url('api/v1/school/fees/remind') ?>"><i class="bi bi-whatsapp"></i> تذكير بواتساب</button><?php endif; ?><?php endif; ?><?php if (can('reports.export')): ?><a class="btn btn-outline-success" href="<?= url('school/fees/arrears.xlsx?section_id=' . (int)$sectionId) ?>"><i class="bi bi-file-earmark-excel"></i> Excel</a><?php endif; ?></div></form>
<div class="d-flex flex-wrap gap-3 mb-3"><?php foreach ($totals as $c => $v): ?><div class="card-s py-2 px-3"><span class="text-muted small">إجمالي المتأخر</span> <strong class="text-danger"><?= number_format((float)$v, 2) ?></strong> <?= e($c) ?></div><?php endforeach; ?></div>
<div class="card-s"><?php if (!$rows): ?><div class="empty-state"><i class="bi bi-emoji-smile"></i>لا توجد متأخرات. 👏</div><?php else: ?><div class="table-responsive"><table class="table table-sm align-middle table-cards"><thead><tr><th><input type="checkbox" id="all" aria-label="تحديد الكل"></th><th>الطالب</th><th>الشعبة</th><th>ولي الأمر</th><th>المتأخر</th><th>منذ</th><th></th></tr></thead><tbody>
<?php foreach ($rows as $x): ?><tr><td><input type="checkbox" class="pick" value="<?= (int)$x['fee_id'] ?>" aria-label="تحديد <?= e($x['full_name']) ?>"></td><td data-label="الطالب"><?= e($x['full_name']) ?></td><td data-label="الشعبة"><?= e($x['grade_name'] . ' / ' . $x['section_name']) ?></td><td data-label="ولي الأمر"><?= e($x['guardian']) ?> <small class="text-muted" dir="ltr"><?= e($x['guardian_phone']) ?></small></td>
  <td data-label="المتأخر" class="text-danger fw-bold"><?= number_format((float)$x['overdue'], 2) ?> <?= e($x['currency']) ?></td><td data-label="منذ"><?= (int)$x['days'] ?> يومًا</td><td><a class="btn btn-sm btn-outline-primary" href="<?= url('school/fees/students/' . (int)$x['fee_id']) ?>">فتح</a></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div>
